  const DESIGNATED_CITIES=["横浜市","川崎市","さいたま市","千葉市","相模原市"];
  function baseMunicipality(area){if(!area)return area;for(const dc of DESIGNATED_CITIES){if(area.indexOf(dc)===0){const m2=area.match(new RegExp("^"+dc+".+?区"));return m2?m2[0]:dc}}if(area.indexOf("郡")!==-1){const m2=area.match(/^.+?郡.+?(?:町|村)/);if(m2)return m2[0]}const m=area.match(/^.+?(?:市|区|町|村)/);return m?m[0]:area}
