  function slugFromOfficialUrl(url){if(!url)return null;let u;try{u=new URL(url)}catch(e){return null}const pathSegs=u.pathname.split("/").filter(Boolean);const candidates=pathSegs.slice().reverse().map(seg=>seg.replace(/\.(html?|php|aspx?)$/i,""));for(const cand of candidates){if(isValidUrlSlugCandidate(cand))return cand.toLowerCase()}const TLD_WORDS=new Set(["jp","com","net","org","co","go","ne","or","ac","info"]);const hostParts=(u.hostname||"").toLowerCase().split(".").filter(h=>h&&h!=="www"&&!TLD_WORDS.has(h));for(const cand of hostParts){if(isValidUrlSlugCandidate(cand))return cand.toLowerCase()}return null}
