  function isKatakanaOnly(name){for(const ch of name){if("・ー ｰ　".indexOf(ch)!==-1)continue;if(/^[a-zA-Z0-9\-&'.]$/.test(ch))continue;const code=ch.codePointAt(0);if(code>=12448&&code<=12543)continue;return false}return true}
  function katakanaToRomaji(text){const out=[];const chars=Array.from(text);const n=chars.length;let i=0;while(i<n){const ch=chars[i];if(ch==="\u30C3"&&i+1<n){const two2=chars[i+1]+(chars[i+2]||"");const one=chars[i+1];const nextRoma=YOUON_MAP[two2]||KATAKANA_MAP[one];if(nextRoma&&"aiueo".indexOf(nextRoma[0])===-1){out.push(nextRoma[0])}i+=1;continue}const two=ch+(chars[i+1]||"");if(YOUON_MAP[two]){out.push(YOUON_MAP[two]);i+=2;continue}if(ch==="\u30FC"){if(out.length&&out[out.length-1]){const last=out[out.length-1];out.push(last[last.length-1])}i+=1;continue}if(KATAKANA_MAP[ch]!==void 0){out.push(KATAKANA_MAP[ch]);i+=1;continue}if(ch==="\u30FB"||ch===" "||ch==="\u3000"){out.push("-");i+=1;continue}if(/^[a-zA-Z0-9\-]$/.test(ch)){out.push(ch.toLowerCase());i+=1;continue}return null}return out.join("").replace(/-+/g,"-")}
  function facilitySlugAndMethod(spot){const urlCand=slugFromOfficialUrl(spot.officialUrl);if(urlCand)return{slug:urlCand,method:"url"};if(isKatakanaOnly(spot.name)){const r=katakanaToRomaji(spot.name);if(r){const cleaned=r.replace(/^-|-$/g,"");if(cleaned.length>=2)return{slug:cleaned,method:"katakana"}}}return{slug:slugifyPart(spot.name)||"spot",method:"japanese"}}
